//
// NandTier terminal font, generated by hw/video/gen_font.py -- edit the
// glyph drawings there and regenerate instead of editing this file.
//
// Combinational: lit = 1 when column col (0..4, left to right) of row
// row (0..7) of character code is lit. Codes outside 0x20..0x7E are blank.

`timescale 1 ns / 1 ps

module nt_font_rom (
	input  [6:0] code,
	input  [2:0] row,
	input  [2:0] col,
	output       lit
);
	reg [39:0] glyph;

	always @* begin
		case (code)
			7'h20: glyph = 40'h0000000000;  //  
			7'h21: glyph = 40'h0100421084;  // !
			7'h22: glyph = 40'h000000014A;  // "
			7'h23: glyph = 40'h0295F57D4A;  // #
			7'h24: glyph = 40'h013C5751E4;  // $
			7'h25: glyph = 40'h00E6820B38;  // %
